PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE hot_items (
            id            TEXT PRIMARY KEY,
            platform      TEXT NOT NULL,
            rank          INTEGER NOT NULL,
            title         TEXT NOT NULL,
            hot_value     INTEGER,
            url           TEXT NOT NULL,
            tags          TEXT NOT NULL DEFAULT '[]',
            summary       TEXT,
            first_seen    INTEGER NOT NULL,
            last_seen     INTEGER NOT NULL,
            source_trust  TEXT NOT NULL
        );
CREATE TABLE hot_embeddings (
            id         TEXT PRIMARY KEY,
            embedding  BLOB NOT NULL,
            platform   TEXT NOT NULL,
            first_seen INTEGER NOT NULL,
            FOREIGN KEY (id) REFERENCES hot_items(id) ON DELETE CASCADE
        );
CREATE TABLE fetch_logs (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            platform    TEXT NOT NULL,
            started_at  INTEGER NOT NULL,
            duration_ms INTEGER NOT NULL,
            status      TEXT NOT NULL,
            item_count  INTEGER NOT NULL DEFAULT 0,
            error       TEXT
        );
CREATE TABLE profile (
            key        TEXT PRIMARY KEY,
            value      TEXT NOT NULL,
            updated_at INTEGER NOT NULL
        );
CREATE TABLE feedback (
            id      INTEGER PRIMARY KEY AUTOINCREMENT,
            hot_id  TEXT NOT NULL,
            action  TEXT NOT NULL,
            at      INTEGER NOT NULL
        );
CREATE TABLE pet_state (
            key        TEXT PRIMARY KEY,
            value      TEXT NOT NULL,
            updated_at INTEGER NOT NULL
        );
PRAGMA writable_schema=ON;
CREATE TABLE IF NOT EXISTS sqlite_sequence(name,seq);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_hot_platform ON hot_items(platform);
CREATE INDEX idx_hot_first_seen ON hot_items(first_seen);
PRAGMA writable_schema=OFF;
COMMIT;
